// Regenerates bundle.ts from the per-language template files: node api/src/ai/templates/build-bundle.mjs
// The compiled API (dist/) ships without .hbs files, so it reads the bundled copy; tests/api-i18n.test.ts
// fails when the bundle and the files differ.
import { readdirSync, readFileSync, writeFileSync } from 'node:fs';
import path from 'node:path';
import { fileURLToPath } from 'node:url';

const dir = path.dirname(fileURLToPath(import.meta.url));
const LANGS = ['en', 'hi', 'te'];
const isTemplateFile = (name) => name.endsWith('.hbs') || name === 'labels.json';

const files = {};
for (const lang of LANGS) {
  files[lang] = {};
  for (const name of readdirSync(path.join(dir, lang)).filter(isTemplateFile).sort()) {
    files[lang][name] = readFileSync(path.join(dir, lang, name), 'utf8').replace(/\r\n/g, '\n');
  }
}

const out = `// Generated by build-bundle.mjs from api/src/ai/templates/{en,hi,te}/. Do not edit by hand: change the .hbs or
// labels.json files and run \`node api/src/ai/templates/build-bundle.mjs\`.
export const TEMPLATE_FILES: Record<string, Record<string, string>> = ${JSON.stringify(files, null, 2)};
`;
writeFileSync(path.join(dir, 'bundle.ts'), out);
console.log(`bundle.ts: ${LANGS.map((l) => `${l} ${Object.keys(files[l]).length} files`).join(', ')}`);
